import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const sources = [
  'src/core/geometry.js',
  'src/ui/tool-layout.js',
  'src/ui/tool-config.js',
  'src/ui/workspace-layout-controller.js',
  'src/ui/layers-panel-controller.js',
  'src/ui/paths-controller.js',
  'src/ui/color-management-controller.js',
  'src/ui/toolbar-controller.js',
  'src/ui/menu-controller.js',
  'src/ui/modal-controller.js',
  'src/interaction/pointer-lifecycle-router.js',
  'src/core/history.js',
  'src/core/io.js',
  'src/core/pixels.js',
  'src/core/pixel-buffer.js',
  'src/core/color-management.js',
  'src/core/recovery.js',
  'src/core/layer-styles.js',
  'src/core/adjustments.js',
  'src/core/state.js',
  'src/ui/layer-blending-controller.js',
  'src/ui/text-edit-controller.js',
  'src/ui/text-settings-controller.js',
  'src/ui/smart-filter-controller.js',
  'src/workspace/session-controller.js',
  'src/workspace/recovery-controller.js',
  'src/core/color.js',
  'src/core/pixel-worker.js',
  'src/core/render.js',
  'src/painting/controller.js',
  'src/painting/command-controller.js',
  'src/retouch/controller.js',
  'src/painting/gesture-controller.js',
  'src/selection/gesture-controller.js',
  'src/selection/raster-mutation-controller.js',
  'src/selection/mask-controller.js',
  'src/selection/vector-mask-controller.js',
  'src/selection/clipboard-controller.js',
  'src/document/import-controller.js',
  'src/document/smart-object-controller.js',
  'src/document/psd-native-metadata-plans.js',
  'src/document/psd-import-semantics.js',
  'src/document/psd-import-controller.js',
  'src/document/psd-export-controller.js',
  'src/formats/psd.js',
  'src/document/psd-smart-object-resource.js',
  'src/main.js',
];

function stripModules(source, filename) {
  let text = source
    .replace(/^\s*import\s+[\s\S]*?from\s+['\"][^'\"]+['\"];?\s*$/gm, '')
    .replace(/^\s*import\s+['\"][^'\"]+['\"];?\s*$/gm, '')
    .replace(/^\s*export\s+(?=(?:async\s+)?function\b|class\b|const\b|let\b|var\b)/gm, '');
  if (/^\s*(?:import|export)\b/m.test(text)) {
    throw new Error(`Unsupported module syntax remains in ${filename}`);
  }
  return text.trim();
}

function stripBuildMeta(source) {
  return source.replace(/^  <meta name="application-build" content="[^"]*" \/>\r?\n/m, '');
}

function stampBuildMeta(source, buildId) {
  const marker = `  <meta name="application-build" content="${buildId}" />`;
  if (/^  <meta name="application-build" content="[^"]*" \/>$/m.test(source)) {
    return source.replace(/^  <meta name="application-build" content="[^"]*" \/>$/m, marker);
  }
  const versionMeta = /^(  <meta name="application-version" content="[^"]*" \/>)$/m;
  if (!versionMeta.test(source)) throw new Error('application-version meta marker is missing from index.html');
  return source.replace(versionMeta, `$1\n${marker}`);
}

function hashBuild(parts) {
  let hash = 0xcbf29ce484222325n;
  const prime = 0x100000001b3n;
  const step = value => {
    hash ^= BigInt(value & 0xff);
    hash = BigInt.asUintN(64, hash * prime);
    hash ^= BigInt((value >>> 8) & 0xff);
    hash = BigInt.asUintN(64, hash * prime);
  };
  for (const part of parts) {
    for (let i = 0; i < part.length; i += 1) step(part.charCodeAt(i));
    step(0xffff);
  }
  return hash.toString(16).padStart(16, '0');
}

const chunks = [];
for (const file of sources) {
  const source = await readFile(resolve(root, file), 'utf8');
  chunks.push(`// ---- ${file} ----\n${stripModules(source, file)}`);
}
const banner = `/* ZeTer Photo Editor browser bundle. Generated by tools/build-bundle.mjs. */\n(function(){\n'use strict';\n`;
const footer = `\n})();\n`;
const bundle = banner + chunks.join('\n\n') + footer;

const [indexSource, stylesSource, packageText] = await Promise.all([
  readFile(resolve(root, 'index.html'), 'utf8'),
  readFile(resolve(root, 'src/styles.css'), 'utf8'),
  readFile(resolve(root, 'package.json'), 'utf8'),
]);
const packageJson = JSON.parse(packageText);
const normalizedIndex = stripBuildMeta(indexSource);
const buildId = hashBuild([normalizedIndex, stylesSource, bundle]);
const stampedIndex = stampBuildMeta(indexSource, buildId);
const versionManifest = JSON.stringify({ version: packageJson.version, build: buildId }, null, 2) + '\n';

await Promise.all([
  writeFile(resolve(root, 'src/app.bundle.js'), bundle, 'utf8'),
  writeFile(resolve(root, 'index.html'), stampedIndex, 'utf8'),
  writeFile(resolve(root, 'version.json'), versionManifest, 'utf8'),
]);
console.log(`Built src/app.bundle.js and cache manifest ${buildId}`);
